/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::TRUSTEE_NOT_HELD,
    error_codes::NO_DEALING,
    error_codes::CEREMONY_INVALID,
    error_codes::NO_COMPLAINT,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vta/pcs/trustee/justify:trusteeNotHeld`
    ///
    /// The VTA holds no `authentication` key of `trustee` that the caller may act as, or the manifest does not name `trustee` as a trustee.
    ///
    /// Declared `retryable: false`.
    pub const TRUSTEE_NOT_HELD: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/pcs/trustee/justify:trusteeNotHeld",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vta/pcs/trustee/justify:noDealing`
    ///
    /// This VTA has not dealt for the trustee in this election.
    ///
    /// Declared `retryable: false`.
    pub const NO_DEALING: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/pcs/trustee/justify:noDealing",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vta/pcs/trustee/justify:ceremonyInvalid`
    ///
    /// A step of `ceremony` is not its trustee's (CONVENTIONS §9.6).
    ///
    /// Declared `retryable: false`.
    pub const CEREMONY_INVALID: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/pcs/trustee/justify:ceremonyInvalid",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
    /// `vta/pcs/trustee/justify:noComplaint`
    ///
    /// No confirmation in `ceremony` from the trustee at `recipient` complains of this trustee.
    ///
    /// Declared `retryable: false`.
    pub const NO_COMPLAINT: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/pcs/trustee/justify:noComplaint",
        retryable: false,
        details_schema: ::core::option::Option::None,
    };
}
